using Microsoft.Dynamics365.LocalizationFramework;
using Microsoft.Dynamics365.LocalizationFramework.Format.FileGeneration;

/// <summary>
/// designed from AVA
/// </summary>
public class AVAERMemoryDestinationFactory implements ERIFileDestinationFactory, ERIFileDestinationFactoryPostProcessor
{
    private ERIFileDestinationFactory       originDestinationFactory;
    AVAERReportToMemory                     erReportToMemory;

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_fileDestination">_fileDestination</param>
/// <param name = "_identification">_identification</param>
/// <param name = "_rootContext">_rootContext</param>
/// <param name = "_root">_root</param>
/// <returns>ERIDataDrivenFileDestination</returns>
public ERIDataDrivenFileDestination createPrintMgmtDestination(
    ERIFileDestination _fileDestination,
    ERIObjectIdentificationStrategy _identification,
    ERTextFormatDataContext _rootContext,
    ERTextFormatIFileComponent _root)
{
    ERIDataDrivenFileDestination dataDrivenDestination = originDestinationFactory.createPrintMgmtDestination(
        _fileDestination,
        _identification,
        _rootContext,
        _root);

    IFileDestinationHost fileDestinationHost = dataDrivenDestination as IFileDestinationHost;
    if (fileDestinationHost)
    {
        fileDestinationHost.FileDestination = AVAERMemoryDestination::construct(
            fileDestinationHost.get_FileDestination(),
            erReportToMemory);
    }

    return dataDrivenDestination;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_originDestinationFactory">_originDestinationFactory</param>
/// <param name = "_erReportToMemory">_erReportToMemory</param>
/// <returns>AVAERMemoryDestinationFactory</returns>
public static AVAERMemoryDestinationFactory construct(ERIFileDestinationFactory _originDestinationFactory, AVAERReportToMemory      _erReportToMemory)
{
    AVAERMemoryDestinationFactory destinationFactory = new AVAERMemoryDestinationFactory(_originDestinationFactory, _erReportToMemory);

    ERIFileDestinationFactoryPostProcessorsHost factoryPostProcessing = ERCast::asObject(destinationFactory.originDestinationFactory) as ERIFileDestinationFactoryPostProcessorsHost;

    if (factoryPostProcessing)
    {
        factoryPostProcessing.addDestinationPostProcessor(destinationFactory);
    }
    return destinationFactory;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_originDestinationFactory">_originDestinationFactory</param>
/// <param name = "_erReportToMemory">_erReportToMemory</param>
protected void new(ERIFileDestinationFactory _originDestinationFactory, AVAERReportToMemory      _erReportToMemory)
{
    originDestinationFactory = _originDestinationFactory;
    erReportToMemory = _erReportToMemory;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_sourceDestination">_sourceDestination</param>
/// <returns>ERIFileDestination</returns>
public ERIFileDestination processDestinationAfterCreation(ERIFileDestination _sourceDestination)
{
    return AVAERMemoryDestination::construct(_sourceDestination, erReportToMemory);
}
